## Why This Is Asked

This question evaluates the ability to design a low-latency, ordered broadcast path with backpressure and dynamic scaling for a high-traffic chat system—similar to workloads at Discord, Cloudflare, and data platforms.

## Key Concepts

- **Per-room ordering** via per-room sequence numbers or monotonically increasing room-level sequence IDs
- **Bounded queues** with backpressure signaling (e.g., pushback, drop policies)
- **Dynamic worker scaling** per room based on queue depth or throughput metrics
- **Event prioritization** and graceful degradation under load
- **Testing strategies** for concurrency, ordering guarantees, and failure scenarios

## Solution Overview

Use per-room sequence numbers and per-room FIFO buffers. Route events through a central bounded queue to a per-room dispatcher, then to pools of workers dedicated to each room. Maintain order by storing the global or room-level sequence number in each event and processing events in per-room priority queues ordered by this sequence number.

## Code Example

```go
package main

import (
	"context"
	"sync"
	"time"
)

type EventType int
const (
	EventTypeMessage EventType = iota
	EventTypeJoin
	EventTypeLeave
)

type Event struct {
	RoomID   string
	EventID  string
	Type     EventType
	Payload  string
	SeqNum   int64
}

type Room struct {
	ID           string
	mu           sync.RWMutex
	buffer       []Event
	capacity     int
	workers      int
	clients      map[chan<- Event]struct{}
	sequenceNum  int64
}

func NewRoom(id string, capacity int) *Room {
	return &Room{
		ID:       id,
		capacity: capacity,
		clients:  make(map[chan<- Event]struct{}),
	}
}

func (r *Room) PushEvent(e Event) bool {
	r.mu.Lock()
	defer r.mu.Unlock()

	if len(r.buffer) >= r.capacity {
		return r.handleBackpressure(e)
	}

	r.buffer = append(r.buffer, e)
	return true
}

func (r *Room) handleBackpressure(e Event) bool {
	if e.Type == EventTypeJoin || e.Type == EventTypeLeave {
		r.buffer = append(r.buffer, e)
		if len(r.buffer) > r.capacity {
			r.buffer = r.buffer[1:]
		}
		return true
	}
	return false
}

func (r *Room) Broadcast(ctx context.Context) {
	ticker := time.NewTicker(10 * time.Millisecond)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			r.mu.RLock()
			if len(r.buffer) == 0 {
				r.mu.RUnlock()
				continue
			}
			event := r.buffer[0]
			r.buffer = r.buffer[1:]
			clients := make([]chan<- Event, 0, len(r.clients))
			for ch := range r.clients {
				clients = append(clients, ch)
			}
			r.mu.RUnlock()

			for _, ch := range clients {
				select {
				case ch <- event:
				default:
				}
			}
		}
	}
}

type Distributor struct {
	mu      sync.RWMutex
	rooms   map[string]*Room
	input   chan Event
	wg      sync.WaitGroup
	ctx     context.Context
	cancel  context.CancelFunc
}

func NewDistributor(bufferPerRoom int) *Distributor {
	ctx, cancel := context.WithCancel(context.Background())
	return &Distributor{
		rooms:  make(map[string]*Room),
		input:  make(chan Event, 10000),
		ctx:    ctx,
		cancel: cancel,
	}
}

func (d *Distributor) GetRoom(roomID string) *Room {
	d.mu.Lock()
	defer d.mu.Unlock()

	if room, ok := d.rooms[roomID]; ok {
		return room
	}

	room := NewRoom(roomID, 1000)
	d.rooms[roomID] = room
	d.wg.Add(1)
	go func() {
		defer d.wg.Done()
		room.Broadcast(d.ctx)
	}()
	return room
}

func (d *Distributor) Run() {
	for {
		select {
		case <-d.ctx.Done():
			return
		case event := <-d.input:
			room := d.GetRoom(event.RoomID)
			room.PushEvent(event)
		}
	}
}

func (d *Distributor) Publish(event Event) {
	select {
	case d.input <- event:
	default:
	}
}

func (d *Distributor) Shutdown() {
	d.cancel()
	close(d.input)
	d.wg.Wait()
}

func main() {
	d := NewDistributor(1000)
	go d.Run()

	d.Publish(Event{
		RoomID:  "room-1",
		EventID: "evt-1",
		Type:    EventTypeJoin,
		Payload: "user-1 joined",
	})

	time.Sleep(100 * time.Millisecond)
	d.Shutdown()
}
```

## Test Plan

1. **Ordering Tests**: Publish 1000 events per room out of order; verify they are delivered in sequence number order.
2. **Backpressure Tests**: Fill buffers to capacity; verify join/leave events are preserved while messages are dropped.
3. **Concurrency Tests**: Run 10 producers and 10 consumers per room simultaneously; check for race conditions and data races.
4. **Dynamic Scaling Tests**: Simulate burst traffic; verify worker count increases and decreases based on queue depth.
5. **Failure Recovery**: Kill rooms mid-broadcast; verify system continues operating and new rooms spawn correctly.
6. **Latency Tests**: Measure end-to-end latency under load; ensure p99 < 50ms for priority events.

## Why This Is Asked
This question tests the ability to design a cross-stream, windowed join with per-key ordering under backpressure—a common pattern in production systems like Databricks Structured Streaming and MongoDB Change Stream implementations.

## Key Concepts
- **Cross-stream joins with per-device keys**: Joining sensor readings (stream A) with status updates (stream B) requires partitioning by device ID to co-locate related events.
- **5-second tumbling windows and watermarks**: Tumbling windows provide non-overlapping, fixed-size time boundaries; watermarks track event time progress and enable safe window completion.
- **Per-key buffers and ordered emission**: Each device maintains separate queues per stream, ensuring in-order processing within each device partition.
- **Backpressure and dynamic worker scaling**: Backpressure signals prevent memory exhaustion when downstream processing cannot keep pace; workers adapt to throughput changes.
- **Late-data handling policy**: Events arriving after the watermark but within the allowed lateness threshold are replayed from buffers to maintain correctness.

## Code Example
```javascript
class WindowManager {
  constructor(windowSec) {
    this.windowSize = windowSec * 1000;
    this.buffers = new Map();
    this.watermark = 0;
    this.pendingJoins = new Map();
  }

  onEvent(event, stream) {
    const key = event.deviceId;
    const timestamp = event.timestamp;

    if (!this.buffers.has(key)) {
      this.buffers.set(key, { A: [], B: [] });
    }

    const buffer = this.buffers.get(key);
    buffer[stream].push(event);
    buffer[stream].sort((a, b) => a.timestamp - b.timestamp);

    this.watermark = Math.max(this.watermark, timestamp);
  }

  processWindow() {
    const windowEnd = this.watermark - (this.watermark % this.windowSize);
    const windowStart = windowEnd - this.windowSize;

    for (const [key, buffer] of this.buffers) {
      const joined = this.joinBuffers(buffer, windowStart, windowEnd);
      if (joined.length > 0) {
        this.emit(joined, key);
      }
    }
  }

  joinBuffers(buffer, start, end) {
    const results = [];
    const relevantA = buffer.A.filter(e => e.timestamp >= start && e.timestamp < end);
    const relevantB = buffer.B.filter(e => e.timestamp >= start && e.timestamp < end);

    for (const a of relevantA) {
      for (const b of relevantB) {
        if (Math.abs(a.timestamp - b.timestamp) <= 1000) {
          results.push({ ...a, ...b });
        }
      }
    }
    return results;
  }

  emit(joined, key) {
    console.log(`Emitting ${joined.length} joined events for device ${key}`);
  }
}

// Usage
const wm = new WindowManager(5);
wm.onEvent({ deviceId: 'dev1', timestamp: 1000, type: 'A', value: 23 }, 'A');
wm.onEvent({ deviceId: 'dev1', timestamp: 1500, type: 'B', status: 'active' }, 'B');
wm.processWindow();
```

